    def set_priority(self, quest_id, priority, *, expected_version, actor):
        if actor != "local_user" or type(priority) is not int or not 1 <= priority <= 5:
            raise DomainError("Invalid priority or actor")
        with self.store.unit_of_work() as work:
            quest = work.get_quest(quest_id)
            if quest is None:
                raise KeyError(quest_id)
            if quest["version"] != expected_version:
                raise QuestVersionConflict("Quest version conflict")
            if quest["status"] in {"completed", "failed", "cancelled", "rejected"}:
                raise DomainError("Terminal Quest cannot be reprioritized")
            cursor = work.connection.execute(
                "UPDATE quests SET priority=?,version=version+1,updated_at=? WHERE id=? AND version=?",
                (priority, now_iso(), quest_id, expected_version),
            )
            if cursor.rowcount != 1:
                raise QuestVersionConflict("Quest version conflict")
            work.append_event(
                ForgeEvent(
                    event_type="quest.priority_changed",
                    quest_id=quest_id,
                    payload={"priority": priority, "actor": actor},
                )
            )
            return work.get_quest(quest_id)

    def readiness(self, quest_id):
        with self.store.connection() as connection:
            connection.execute("BEGIN")
            quest = connection.execute("SELECT * FROM quests WHERE id=?", (quest_id,)).fetchone()
            if quest is None:
                raise KeyError(quest_id)
            plan = connection.execute(
                "SELECT * FROM quest_plans WHERE quest_id=? AND revision=?",
                (quest_id, quest["plan_revision"]),
            ).fetchone()
            if plan is None:
                raise KeyError(quest_id)
            rows = connection.execute(
                "SELECT node_key,status FROM task_nodes WHERE plan_id=?", (plan["id"],)
            ).fetchall()
            edges = connection.execute(
                "SELECT source,target,condition FROM task_edges WHERE plan_id=?",
                (plan["id"],),
            ).fetchall()
            connection.commit()
        states = {row["node_key"]: row["status"] for row in rows}
        result = {}
        terminal = {"succeeded", "failed", "skipped"}
        for key, status in states.items():
            if (
                status != "proposed"
            if row["conversation_id"] != "main" or row["role"] != "user":
                continue
            # A caller/model-provided metadata field is not enough to establish
            # Quest association. Router explicitly supplies it when recording.
            self.index_message(row["id"], connection=connection)
        if rows:
            connection.execute(
                "UPDATE constraint_index_cursor SET message_rowid=? WHERE singleton=1",
                (rows[-1]["rowid"],),
            )
        return {"has_more": len(rows) == limit, "processed": len(rows)}

    def _record_item(self, connection, row, *, conflicts=True):
        if row["status"] != "active":
            return None
        expiry = row["valid_until"]
        if expiry and datetime.fromisoformat(expiry) <= datetime.now(UTC):
            return None
        try:
            source = self._source(connection, row["source_message_id"])
        except DomainError:
            return None
        if _message_hash(source) != row["source_sha256"]:
            return None
        if connection.execute(
            "SELECT 1 FROM revoked_memory_sources WHERE source_ref=?",
            (f"message:{source['id']}",),
        ).fetchone():
            return None
        if row["confirmation_message_id"]:
            try:
                confirmation = self._source(connection, row["confirmation_message_id"])
            except DomainError:
                return None
            if _message_hash(confirmation) != row["confirmation_sha256"]:
                return None
        potential_conflict = False
        if conflicts and row["dimension"] != "unspecified":
            others = connection.execute(
                """SELECT * FROM constraint_records WHERE dimension=? AND quest_id IS ?
                AND status='active' AND id!=? ORDER BY id LIMIT 101""",
                (row["dimension"], row["quest_id"], row["id"]),
            ).fetchall()
            potential_conflict = len(others) > 100 or any(
                other["statement"] != row["statement"]
                and self._record_item(connection, other, conflicts=False) is not None
                for other in others[:100]
            )
        refs = [f"message:{source['id']}"]
        if row["confirmation_message_id"]:
            refs.append(f"message:{row['confirmation_message_id']}")
        return {
            "id": f"constraint:{row['id']}",
            "statement": row["statement"],
            "kind": "constraint",
            "layer": "L1" if row["quest_id"] else "L2",
            "status": "hypothesis",
            "confirmation_status": row["origin"],
            "source_refs": refs,
            "source_hash": row["source_sha256"],
