import json, sqlite3
from pathlib import Path
for rid in ['20261115T154942Z-L1-eb980c','20261115T154942Z-L2-898b5e']:
 d=json.loads((Path('.local/phase2/runs')/rid/'run.json').read_bytes()); c=sqlite3.connect(Path(d['db_path']).resolve().as_uri()+'?mode=ro',uri=True); c.row_factory=sqlite3.Row; c.execute('PRAGMA query_only=ON');c.execute('BEGIN')
 run=c.execute('SELECT * FROM worker_runs').fetchone()
 capsule=json.loads(c.execute('SELECT capsule_json FROM worker_capsules').fetchone()[0])
 print(json.dumps({'rid':rid,'capsule_keys':list(capsule),'capacity':capsule.get('review_envelope') or capsule.get('worker_capacity'),'output_limit':run['output_limit'],'max_output':run['model_max_output_tokens'],'tool_limit':run['tool_limit']},ensure_ascii=False))
 for r in c.execute('SELECT seq,event_type,payload FROM events WHERE event_type IN (\'worker.model_response_rejected\',\'worker.progress\')'):
  p=json.loads(r['payload'])
  if r['event_type']=='worker.model_response_rejected':print(json.dumps({'seq':r['seq'],'type':r['event_type'],'diagnostics':p.get('diagnostics'),'reason':p.get('reason_code')},ensure_ascii=False))
 for r in c.execute('SELECT ordinal,role,message_json FROM worker_messages ORDER BY ordinal'):
  m=json.loads(r['message_json']); text=str(m.get('content','')); brief={'ordinal':r['ordinal'],'role':r['role'],'chars':len(text),'bytes':len(text.encode()),'tool_names':[x.get('function',{}).get('name') for x in m.get('tool_calls',[])]}
  try:
   p=json.loads(text)
   if isinstance(p,dict) and 'repair_request'in p: brief['repair_request']=p['repair_request']
   if isinstance(p,dict) and 'repair'in p:brief['repair']=p['repair']
  except ValueError: pass
  if 'Correct the failure' in text or 'repair_request' in text: brief['repair_content']=text[:2200]
  print(json.dumps(brief,ensure_ascii=False))
 print(json.dumps({'changes':c.total_changes}))
 c.close()
'@ | & 'backend/.venv/Scripts/python.exe' -","workdir":"D:\Competition_this\Agent","max_output_tokens":6000}));

